package com.example.baget.cash;
import com.example.baget.users.*;
import com.example.baget.calculation.preview.PreviewException;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.constraints.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import java.math.BigDecimal;
import java.util.*;
@Service
@Transactional(isolation=Isolation.READ_COMMITTED)
public class CashService {
 private final JdbcTemplate db;private final UsersRepository users;private final ObjectMapper json;
 public CashService(JdbcTemplate db,UsersRepository users,ObjectMapper json){this.db=db;this.users=users;this.json=json;}
 static boolean role(User u,String... roles){return u.getRoles().stream().anyMatch(r->Set.of(roles).contains(r.getName()));}
 public static boolean editor(User u){return role(u,"ROLE_ADMIN","ROLE_ACCOUNTANT","ROLE_BOOKKEEPER","ROLE_COUNTER");}
 private User user(Authentication a){if(a==null||!a.isAuthenticated())throw denied();var u=users.findByUsername(a.getName()).orElseThrow(CashService::denied);if(!u.isEnabled()||!role(u,"ROLE_ADMIN","ROLE_ACCOUNTANT","ROLE_BOOKKEEPER","ROLE_COUNTER","ROLE_MANAGER","ROLE_SELLER","ROLE_LEVEL2"))throw denied();return u;}
 private void branch(User u,long id){if(!role(u,"ROLE_ADMIN")&&u.getAllowedBranches().stream().noneMatch(b->b.getBranchNo()==id))throw denied();}
 private void own(long branch){if(!Long.valueOf(1).equals(db.queryForObject("SELECT COUNT(*) FROM branch_commercial_settings WHERE branch_no=? AND mode='OWN'",Long.class,branch)))throw bad("Каса підприємства може належати лише власній філії");}
 private void serialize(){db.queryForObject("SELECT id FROM cash_control WHERE id=1 FOR UPDATE",Integer.class);}
 private Map<String,Object> account(long id){var rows=db.queryForList("SELECT * FROM cash_accounts WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw bad("Касу або рахунок не знайдено");return rows.get(0);}
 private void view(User u,Map<String,Object> account){if("BRANCH_CASH".equals(account.get("kind")))branch(u,num(account,"branch_no"));else if(!editor(u))throw denied();}
 private void ready(Map<String,Object> account){own(num(account,"branch_no"));if(!yes(account.get("initialized")))throw bad("Спочатку встановіть початковий залишок каси / рахунку");}
 private BigDecimal balance(long id){return db.queryForObject("SELECT COALESCE(SUM(CASE WHEN direction='IN' THEN amount ELSE -amount END),0) FROM ledger_entries WHERE cash_account_id=?",BigDecimal.class,id);}
 static void positive(BigDecimal n){if(n==null||n.signum()<=0||n.compareTo(new BigDecimal("999999999.99"))>0||n.stripTrailingZeros().scale()>2)throw bad("Вкажіть додатну суму до двох знаків після коми");}
 private void enough(long id,BigDecimal amount){if(balance(id).compareTo(amount)<0)throw bad("Недостатньо коштів у касі / на рахунку");}
 private void post(Map<String,Object> account,String direction,String category,BigDecimal amount,User u,Long transfer,Long reward,String note){
  db.update("INSERT INTO ledger_entries(branch_id,direction,category,amount,created_at,created_by,cash_account_id,cash_transfer_id,reward_entry_id,reference,note) VALUES(?,?,?,?,CURRENT_TIMESTAMP(6),?,?,?,?,?,?)",account.get("branch_no"),direction,category,amount,u.getId(),account.get("id"),transfer,reward,transfer!=null?"CASH-TRANSFER-"+transfer:reward!=null?"REWARD-"+reward:"CASH-OPENING",note);
 }
 private Object prior(String operation,String key,Object payload,User u){
  try{if(!UUID.fromString(key).toString().equals(key))throw new IllegalArgumentException();}catch(Exception e){throw bad("Некоректний ключ операції");}
  var rows=db.queryForList("SELECT actor,operation,payload,result FROM cash_requests WHERE request_key=?",key);if(rows.isEmpty())return null;var r=rows.get(0);
  try{if(!u.getUsername().equals(r.get("actor"))||!operation.equals(r.get("operation"))||!json.readTree(encode(payload)).equals(json.readTree(r.get("payload").toString())))throw bad("Ключ використано для іншої операції");return json.readValue(r.get("result").toString(),Map.class);}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException(e);}
 }
 private Object remember(String operation,String key,Object payload,Object result,User u){db.update("INSERT INTO cash_requests(request_key,actor,operation,payload,result) VALUES(?,?,?,?,?)",key,u.getUsername(),operation,encode(payload),encode(result));return result;}
 private String encode(Object v){try{return json.writeValueAsString(v);}catch(Exception e){throw new IllegalStateException(e);}}
 public record Create(@NotBlank String requestKey,@NotBlank @Size(max=150) String name,@NotBlank String kind,@Positive long branchNo){}
 public Object create(Create r,Authentication a){var u=user(a);if(!role(u,"ROLE_ADMIN"))throw denied();serialize();var prior=prior("CREATE",r.requestKey(),r,u);if(prior!=null)return prior;own(r.branchNo());if(!Set.of("BRANCH_CASH","CENTRAL_CASH","BANK").contains(r.kind()))throw bad("Невідомий тип рахунку");String code="CENTRAL_CASH".equals(r.kind())?"central":"BRANCH_CASH".equals(r.kind())?"branch-"+r.branchNo():"bank-"+UUID.randomUUID();if(db.queryForObject("SELECT COUNT(*) FROM cash_accounts WHERE code=?",Long.class,code)>0)throw bad("Така каса вже існує");db.update("INSERT INTO cash_accounts(code,name,kind,branch_no) VALUES(?,?,?,?)",code,r.name().trim(),r.kind(),r.branchNo());long id=db.queryForObject("SELECT LAST_INSERT_ID()",Long.class);
  if("CENTRAL_CASH".equals(r.kind()))db.update("INSERT INTO cash_accounts(code,name,kind,branch_no,initialized,opened_at) VALUES('transit','Кошти в дорозі','TRANSIT',?,1,CURRENT_TIMESTAMP(6))",r.branchNo());
  return remember("CREATE",r.requestKey(),r,Map.of("id",id),u);
 }
 public record Opening(@NotBlank String requestKey,@Positive long accountId,@NotNull @DecimalMin("0") @DecimalMax("999999999.99") @Digits(integer=9,fraction=2) BigDecimal amount,@NotBlank @Size(max=1000) String note){}
 public Object opening(Opening r,Authentication a){var u=user(a);if(!role(u,"ROLE_ADMIN"))throw denied();serialize();var prior=prior("OPENING",r.requestKey(),r,u);if(prior!=null)return prior;var acc=account(r.accountId());own(num(acc,"branch_no"));if(yes(acc.get("initialized"))||"TRANSIT".equals(acc.get("kind")))throw bad("Початковий залишок уже встановлено");if(r.amount()==null||r.amount().signum()<0)throw bad("Некоректний залишок");if(r.amount().signum()>0){positive(r.amount());post(acc,"IN","CASH_OPENING",r.amount(),u,null,null,r.note());}db.update("UPDATE cash_accounts SET initialized=1,opened_at=CURRENT_TIMESTAMP(6) WHERE id=?",r.accountId());return remember("OPENING",r.requestKey(),r,Map.of("saved",true),u);}
 public record Send(@NotBlank String requestKey,@Positive long sourceId,@Positive long destinationId,@NotNull @Digits(integer=9,fraction=2) BigDecimal amount,@NotBlank @Size(max=1000) String note){}
 public Object send(Send r,Authentication a){var u=user(a);serialize();var from=account(r.sourceId());view(u,from);var prior=prior("SEND",r.requestKey(),r,u);if(prior!=null)return prior;var to=account(r.destinationId());ready(from);ready(to);if(r.sourceId()==r.destinationId()||"TRANSIT".equals(from.get("kind"))||"TRANSIT".equals(to.get("kind")))throw bad("Некоректний напрям передачі");if(!editor(u)&&(!"BRANCH_CASH".equals(from.get("kind"))||!"CENTRAL_CASH".equals(to.get("kind"))))throw denied();if(editor(u))view(u,to);positive(r.amount());enough(r.sourceId(),r.amount());var transitRows=db.queryForList("SELECT id FROM cash_accounts WHERE code='transit'");if(transitRows.isEmpty())throw bad("Спочатку створіть центральну касу");var transit=account(num(transitRows.get(0),"id"));
  db.update("INSERT INTO cash_transfers(source_id,destination_id,transit_id,amount,sent_by,note) VALUES(?,?,?,?,?,?)",r.sourceId(),r.destinationId(),transit.get("id"),r.amount(),u.getUsername(),r.note());long id=db.queryForObject("SELECT LAST_INSERT_ID()",Long.class);post(from,"OUT","CASH_TRANSFER",r.amount(),u,id,null,r.note());post(transit,"IN","CASH_TRANSFER",r.amount(),u,id,null,r.note());return remember("SEND",r.requestKey(),r,Map.of("id",id,"state","SENT"),u);
 }
 public record Receive(@NotBlank String requestKey,@Positive long transferId,@NotNull @Digits(integer=9,fraction=2) BigDecimal amount,@NotBlank @Size(max=1000) String note){}
 public Object receive(Receive r,Authentication a){var u=user(a);if(!editor(u))throw denied();serialize();var rows=db.queryForList("SELECT * FROM cash_transfers WHERE id=? FOR UPDATE",r.transferId());if(rows.isEmpty())throw bad("Передачу не знайдено");var transfer=rows.get(0);var dest=account(num(transfer,"destination_id"));view(u,dest);var prior=prior("RECEIVE",r.requestKey(),r,u);if(prior!=null)return prior;if(!"SENT".equals(transfer.get("state")))throw bad("Передачу вже прийнято");if(u.getUsername().equals(transfer.get("sent_by")))throw bad("Передачу має підтвердити інший бухгалтер або адміністратор");if(r.amount()==null||r.amount().signum()<0||r.amount().stripTrailingZeros().scale()>2)throw bad("Некоректна фактична сума");if(r.amount().compareTo(decimal(transfer,"amount"))!=0){db.update("INSERT INTO cash_transfer_notes(transfer_id,observed_amount,note,actor) VALUES(?,?,?,?)",r.transferId(),r.amount(),r.note(),u.getUsername());return remember("RECEIVE",r.requestKey(),r,Map.of("state","SENT","message","Розбіжність записано. Передача залишається в дорозі до з'ясування"),u);}ready(dest);var transit=account(num(transfer,"transit_id"));enough(num(transit,"id"),r.amount());post(transit,"OUT","CASH_TRANSFER",r.amount(),u,r.transferId(),null,r.note());post(dest,"IN","CASH_TRANSFER",r.amount(),u,r.transferId(),null,r.note());db.update("UPDATE cash_transfers SET state='RECEIVED',received_by=?,received_at=CURRENT_TIMESTAMP(6),received_note=? WHERE id=?",u.getUsername(),r.note(),r.transferId());return remember("RECEIVE",r.requestKey(),r,Map.of("saved",true),u);}
 /** Called in the same payment transaction before posting any ledger entries. */
 @Transactional(propagation=Propagation.MANDATORY)
 public long paymentAccount(User u,long branch,Long requested){if(!u.isEnabled())throw denied();branch(u,branch);own(branch);serialize();Long id=requested;
  if(id==null){var rows=db.queryForList("SELECT id FROM cash_accounts WHERE code=?", "branch-"+branch);if(rows.isEmpty())throw bad("Для філії не налаштовано касу. Зверніться до адміністратора");id=num(rows.get(0),"id");}
  var acc=account(id);ready(acc);String kind=acc.get("kind").toString();if("TRANSIT".equals(kind))throw denied();if("BRANCH_CASH".equals(kind)&&num(acc,"branch_no")!=branch)throw denied();if("CENTRAL_CASH".equals(kind)&&!editor(u))throw denied();return id;
 }
 /** No customer/invoice linkage: payroll never changes customer debt. */
 @Transactional(propagation=Propagation.MANDATORY)
 public void reward(long entryId,Long original,BigDecimal amount,User u){if(!editor(u))throw denied();serialize();Map<String,Object> acc;
  if(original==null){var rows=db.queryForList("SELECT id FROM cash_accounts WHERE code='central'");if(rows.isEmpty())throw bad("Налаштуйте центральну касу для виплати винагород");acc=account(num(rows.get(0),"id"));ready(acc);positive(amount);enough(num(acc,"id"),amount);}
  else {var rows=db.queryForList("SELECT cash_account_id FROM ledger_entries WHERE reward_entry_id=? AND category='MANAGER_REWARD' AND direction='OUT'",original);if(rows.isEmpty())return;acc=account(num(rows.get(0),"cash_account_id"));if(!"CENTRAL_CASH".equals(acc.get("kind")))throw bad("Виплата не пов'язана з центральною касою");ready(acc);positive(amount);}
  post(acc,original==null?"OUT":"IN","MANAGER_REWARD",amount,u,null,entryId,original==null?"Виплата винагороди менеджеру":"Скасування помилкового запису виплати; кошти залишаються у касі");
 }
 public Object options(Authentication a){var u=user(a);var args=new ArrayList<Object>();String filter="";if(!role(u,"ROLE_ADMIN")){var ids=u.getAllowedBranches().stream().map(b->b.getBranchNo()).toList();filter=ids.isEmpty()?" AND 1=0":" AND b.BranchNo IN ("+String.join(",",Collections.nCopies(ids.size(),"?"))+")";args.addAll(ids);}return Map.of("branches",db.queryForList("SELECT b.BranchNo AS id,b.BranchName AS name FROM branches b JOIN branch_commercial_settings s ON s.branch_no=b.BranchNo WHERE s.mode='OWN'"+filter+" ORDER BY b.BranchName",args.toArray()),"canEdit",editor(u),"canConfigure",role(u,"ROLE_ADMIN"));}
 public Object invoicePaymentOptions(long invoice,Authentication a){user(a);var rows=db.queryForList("SELECT branch_id FROM ledger_entries WHERE invoice_id=? AND direction='OUT' AND category IN ('INVOICE_ISSUED','INVOICE_MERGE_OUT') ORDER BY created_at DESC,id DESC LIMIT 1",invoice);if(rows.isEmpty())throw bad("Не визначено філію обліку рахунку");return paymentOptions(num(rows.get(0),"branch_id"),a);}
 public Object paymentOptions(long branch,Authentication a){var u=user(a);branch(u,branch);own(branch);return db.queryForList("SELECT a.id,a.name,a.kind FROM cash_accounts a JOIN branch_commercial_settings s ON s.branch_no=a.branch_no AND s.mode='OWN' WHERE a.initialized=1 AND (a.kind='BANK' OR (a.kind='BRANCH_CASH' AND a.branch_no=?)"+(editor(u)?" OR a.kind='CENTRAL_CASH'":"")+") ORDER BY a.kind,a.name",branch);}
 public Object overview(Authentication a){var u=user(a);var all=db.queryForList("SELECT a.*,b.BranchName AS branchName,COALESCE(SUM(CASE WHEN l.direction='IN' THEN l.amount ELSE -l.amount END),0) AS balance FROM cash_accounts a JOIN branches b ON b.BranchNo=a.branch_no LEFT JOIN ledger_entries l ON l.cash_account_id=a.id GROUP BY a.id,b.BranchName ORDER BY a.id");var visible=all.stream().filter(r->"BRANCH_CASH".equals(r.get("kind"))?(role(u,"ROLE_ADMIN")||u.getAllowedBranches().stream().anyMatch(b->b.getBranchNo()==num(r,"branch_no"))):editor(u)).toList();
  var transfers=db.queryForList("SELECT t.*,(SELECT CONCAT(n.observed_amount,' грн: ',n.note) FROM cash_transfer_notes n WHERE n.transfer_id=t.id ORDER BY n.id DESC LIMIT 1) AS discrepancy,s.name AS sourceName,d.name AS destinationName,s.branch_no AS sourceBranch,d.branch_no AS destinationBranch FROM cash_transfers t JOIN cash_accounts s ON s.id=t.source_id JOIN cash_accounts d ON d.id=t.destination_id WHERE t.state='SENT' ORDER BY t.id").stream().filter(t->editor(u)||u.getAllowedBranches().stream().anyMatch(b->b.getBranchNo()==num(t,"sourceBranch"))).toList();
  return Map.of("accounts",visible,"transfers",transfers,"destinations",db.queryForList("SELECT id,name,kind FROM cash_accounts WHERE kind='CENTRAL_CASH' AND initialized=1"),"canEdit",editor(u),"canConfigure",role(u,"ROLE_ADMIN"));}
 public Object journal(long id,int page,Authentication a){var u=user(a);view(u,account(id));if(page<0||page>100000)throw bad("Некоректна сторінка");var rows=db.queryForList("SELECT l.id,l.direction,l.category,l.amount,l.created_at AS createdAt,l.cash_transfer_id AS transferId,l.reward_entry_id AS rewardEntryId,l.reference,l.note,u.username AS actor FROM ledger_entries l LEFT JOIN users u ON u.id=l.created_by WHERE l.cash_account_id=? ORDER BY l.id DESC LIMIT 51 OFFSET ?",id,page*50);return Map.of("rows",rows.subList(0,Math.min(50,rows.size())),"hasMore",rows.size()>50);}
 static long num(Map<String,Object> m,String k){return ((Number)m.get(k)).longValue();}static BigDecimal decimal(Map<String,Object> m,String k){return new BigDecimal(m.get(k).toString());}static boolean yes(Object o){return Boolean.TRUE.equals(o)||o instanceof Number n&&n.intValue()==1;}
 static PreviewException bad(String m){return new PreviewException(HttpStatus.CONFLICT,"CASH_CONFLICT",m);}static PreviewException denied(){return new PreviewException(HttpStatus.FORBIDDEN,"CASH_ACCESS","Немає доступу до касової операції");}
}
